struct dsu {
    vector<int> p, s;
 
    dsu(int n = 0) {
        init(n);
    }
 
    void init(int n) {
        p.resize(n + 1);
        s.assign(n + 1, 1);
        iota(p.begin(), p.end(), 0);
    }
 
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
 
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (s[a] < s[b]) swap(a, b);
        p[b] = a;
        s[a] += s[b];
        return true;
    }
};
 
struct query {
    int a, b;
};
 
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
 
    int n, m, q;
    cin >> n >> m >> q;
 
    vector<query> e(m + 1);
    for (int i = 1; i <= m; i++) {
        cin >> e[i].a >> e[i].b;
    }
 
    vector<query> qu(q);
    for (int i = 0; i < q; i++) {
        cin >> qu[i].a >> qu[i].b;
    }
 
    vector<int> l(q, 0), r(q, m), ans(q, -1);

 
    while (true) {
        bool any = false;
        vector<vector<int>> bucket(m + 1);
        for (int i = 0; i < q; i++) {
            if (l[i] < r[i]) {
                any = true;
                bucket[(l[i] + r[i]) >> 1].push_back(i);
            }
        }
 
        if (!any) break;
 
        dsu uf(n);
 
        for (int day = 0; day <= m; day++) {
            uf.unite(e[day].a, e[day].b);
 
            for (int id : bucket[day]) {
                if (uf.find(qu[id].a) == uf.find(qu[id].b))
                    r[id] = day;
                else
                    l[id] = day + 1;
            }
        }
    }
 
    dsu dsu(n);
    for (int day = 1; day <= m; day++) {
        dsu.unite(e[day].a, e[day].b);
    }
 
    for (int i = 0; i < q; i++) {
        if (dsu.find(qu[i].a) != dsu.find(qu[i].b)) {
            cout << -1 << '\n';
        } else {
            cout << l[i] << '\n';
        }
    }
}